# Momento en que el pedido llegó a cada estado, según el historial.
def hito(estado):
    return f"MIN(CASE WHEN h.estado = '{estado}' THEN h.fecha_hora END)"


V_TIEMPOS_PEDIDO = f"""
CREATE OR REPLACE VIEW v_tiempos_pedido AS
SELECT
    p.id AS pedido_id,
    p.zona_id,
    p.repartidor_id,
    p.estado,
    p.total,
    p.tiempo_estimado_min,
    p.fecha_creacion,
    p.fecha_entrega,
    TIMESTAMPDIFF(MINUTE, p.fecha_creacion, {hito('PREPARANDO')}) AS min_espera,
    TIMESTAMPDIFF(MINUTE, {hito('PREPARANDO')}, {hito('LISTO')}) AS min_preparacion,
    TIMESTAMPDIFF(MINUTE, {hito('LISTO')}, {hito('EN_CAMINO')}) AS min_despacho,
    TIMESTAMPDIFF(MINUTE, {hito('EN_CAMINO')}, p.fecha_entrega) AS min_viaje,
    TIMESTAMPDIFF(MINUTE, p.fecha_creacion, p.fecha_entrega) AS min_total,
    -- A tiempo = dentro del estimado + 10 min de tolerancia: la misma regla que
    -- dispara las alertas de demora (services.TOLERANCIA_DEMORA_MIN).
    CASE
        WHEN p.fecha_entrega IS NULL THEN NULL
        WHEN TIMESTAMPDIFF(MINUTE, p.fecha_creacion, p.fecha_entrega)
             <= p.tiempo_estimado_min + 10 THEN 1
        ELSE 0
    END AS a_tiempo
FROM daroth_app_pedido p
LEFT JOIN daroth_app_historialestado h ON h.pedido_id = p.id
GROUP BY p.id, p.zona_id, p.repartidor_id, p.estado, p.total, p.tiempo_estimado_min,
         p.fecha_creacion, p.fecha_entrega
"""

V_PEDIDOS_ACTIVOS = """
CREATE OR REPLACE VIEW v_pedidos_activos AS
SELECT
    p.id AS pedido_id,
    p.estado,
    c.nombre AS cliente,
    z.nombre AS zona,
    r.nombre AS repartidor,
    p.direccion_entrega,
    p.total,
    p.tiempo_estimado_min,
    p.fecha_creacion,
    TIMESTAMPDIFF(MINUTE, p.fecha_creacion, UTC_TIMESTAMP()) AS min_transcurridos,
    -- tiempo_estimado_min es UNSIGNED: sin el CAST, la resta negativa desborda.
    GREATEST(0, TIMESTAMPDIFF(MINUTE, p.fecha_creacion, UTC_TIMESTAMP())
                - CAST(p.tiempo_estimado_min AS SIGNED)) AS min_excedidos,
    EXISTS (SELECT 1 FROM daroth_app_alerta a
            WHERE a.pedido_id = p.id AND a.resuelta = 0) AS alerta_pendiente
FROM daroth_app_pedido p
JOIN daroth_app_cliente c ON c.id = p.cliente_id
JOIN daroth_app_zona z ON z.id = p.zona_id
LEFT JOIN daroth_app_repartidor r ON r.id = p.repartidor_id
WHERE p.estado <> 'ENTREGADO'
"""

V_RENDIMIENTO_REPARTIDORES = """
CREATE OR REPLACE VIEW v_rendimiento_repartidores AS
SELECT
    r.id AS repartidor_id,
    r.nombre,
    r.vehiculo,
    r.estado,
    COUNT(t.pedido_id) AS entregas,
    ROUND(AVG(t.min_viaje), 1) AS prom_min_viaje,
    ROUND(AVG(t.min_total), 1) AS prom_min_total,
    ROUND(100 * AVG(t.a_tiempo), 1) AS pct_a_tiempo,
    COALESCE(SUM(t.total), 0) AS facturacion
FROM daroth_app_repartidor r
LEFT JOIN v_tiempos_pedido t ON t.repartidor_id = r.id AND t.estado = 'ENTREGADO'
GROUP BY r.id, r.nombre, r.vehiculo, r.estado
"""

V_DEMANDA_ZONA = """
CREATE OR REPLACE VIEW v_demanda_zona AS
SELECT
    z.id AS zona_id,
    z.nombre,
    z.tiempo_viaje_min,
    COUNT(t.pedido_id) AS pedidos,
    COALESCE(SUM(t.estado = 'ENTREGADO'), 0) AS entregados,
    COALESCE(SUM(CASE WHEN t.estado = 'ENTREGADO' THEN t.total END), 0) AS facturacion,
    ROUND(AVG(t.total), 2) AS ticket_promedio,
    ROUND(AVG(t.min_total), 1) AS prom_min_total,
    ROUND(100 * AVG(t.a_tiempo), 1) AS pct_a_tiempo
FROM daroth_app_zona z
LEFT JOIN v_tiempos_pedido t ON t.zona_id = z.id
GROUP BY z.id, z.nombre, z.tiempo_viaje_min
"""

V_PRODUCTOS_MAS_VENDIDOS = """
CREATE OR REPLACE VIEW v_productos_mas_vendidos AS
SELECT
    pr.id AS producto_id,
    pr.nombre,
    COALESCE(SUM(d.cantidad), 0) AS unidades,
    COUNT(DISTINCT d.pedido_id) AS pedidos,
    COALESCE(SUM(d.cantidad * d.precio_unitario), 0) AS facturacion,
    ROUND(AVG(t.min_preparacion), 1) AS prom_min_preparacion
FROM daroth_app_producto pr
LEFT JOIN daroth_app_detallepedido d ON d.producto_id = pr.id
LEFT JOIN v_tiempos_pedido t ON t.pedido_id = d.pedido_id
GROUP BY pr.id, pr.nombre
"""


